/* DejaVu Sans (http://dejavu-fonts.github.io/, Bitstream Vera license - free to embed)
   Subset: Latin, Latin-Extended, Greek, Cyrillic, currency and punctuation for full UTF-8 CMR output. */
var DEJAVU_SANS = "";
var DEJAVU_SANS_BOLD = "";
(function (jsPDF) {
  var callAddFont = function () {
    this.addFileToVFS("DejaVuSans.ttf", DEJAVU_SANS);
    this.addFont("DejaVuSans.ttf", "DejaVuSans", "normal");
    this.addFileToVFS("DejaVuSans-Bold.ttf", DEJAVU_SANS_BOLD);
    this.addFont("DejaVuSans-Bold.ttf", "DejaVuSans", "bold");
  };
  jsPDF.API.events.push(["addFonts", callAddFont]);
})(window.jspdf.jsPDF);
